namespace sv_29409ba240364f0bb722a9a4f6fbdf8c.Services;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

@using sv_29409ba240364f0bb722a9a4f6fbdf8c.Services

<div class="card mb-2">
    <div class="card-body p-2">
        <h6 class="card-title mb-1">@Task.Title</h6>
        <p class="card-text mb-1"><small class="text-muted">@Task.Assignee</small></p>
        <span class="badge @PriorityClass">@Task.Priority</span>
        <small class="text-muted ms-2">@Task.DueDate.ToString("MMM dd")</small>
        <div class="mt-2 d-flex gap-1">
            @if (CanMoveLeft)
            {
                <button class="btn btn-sm btn-outline-secondary" @onclick="MoveLeft">&larr; Move Left</button>
            }
            @if (CanMoveRight)
            {
                <button class="btn btn-sm btn-outline-secondary" @onclick="MoveRight">Move Right &rarr;</button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<string> OnMoveRequested { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveLeft() => await OnMoveRequested.InvokeAsync("left");
    private async Task MoveRight() => await OnMoveRequested.InvokeAsync("right");
}

@using sv_29409ba240364f0bb722a9a4f6fbdf8c.Services

<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@ColumnName</h5>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          CanMoveLeft="!IsFirst"
                          CanMoveRight="!IsLast"
                          OnMoveRequested="dir => HandleMove(task.Id, dir)" />
            }

            @if (showForm)
            {
                <AddTaskForm OnSave="HandleSave" OnCancel="() => showForm = false" />
            }
            else
            {
                <button class="btn btn-sm btn-outline-primary w-100 mt-2" @onclick="() => showForm = true">
                    + Add Task
                </button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool IsFirst { get; set; }
    [Parameter] public bool IsLast { get; set; }
    [Parameter] public EventCallback<(int TaskId, string Direction)> OnTaskMoved { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }

    private bool showForm;

    private async Task HandleMove(int taskId, string direction)
    {
        await OnTaskMoved.InvokeAsync((taskId, direction));
    }

    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) data)
    {
        await OnTaskCreated.InvokeAsync(data);
        showForm = false;
    }
}

@using sv_29409ba240364f0bb722a9a4f6fbdf8c.Services

<div class="d-flex gap-2 flex-wrap mb-3">
    <span class="badge bg-primary p-2">Total: @Tasks.Count</span>
    <span class="badge bg-info text-dark p-2">To Do: @Tasks.Count(t => t.Status == "To Do")</span>
    <span class="badge bg-warning text-dark p-2">In Progress: @Tasks.Count(t => t.Status == "In Progress")</span>
    <span class="badge bg-success p-2">Done: @Tasks.Count(t => t.Status == "Done")</span>
    <span class="badge bg-danger p-2">Overdue: @OverdueCount</span>
</div>

@code {
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();

    private int OverdueCount => Tasks.Count(t => t.DueDate < DateTime.Today);
}

@page "/board"
@rendermode InteractiveServer
@using sv_29409ba240364f0bb722a9a4f6fbdf8c.Services
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="d-flex align-items-center gap-2">
        <div class="spinner-border spinner-border-sm" role="status"></div>
        <span>Loading tasks...</span>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">@errorMessage</div>
}
else
{
    <BoardStats Tasks="allTasks" />

    <TaskSearchBar SearchText="@searchText" SearchTextChanged="text => { searchText = text; }" />

    <div class="row g-3">
        @for (var i = 0; i < Columns.Length; i++)
        {
            var column = Columns[i];
            var index = i;
            <KanbanColumn ColumnName="@column"
                          Tasks="GetColumnTasks(column)"
                          IsFirst="index == 0"
                          IsLast="index == Columns.Length - 1"
                          OnTaskMoved="HandleTaskMoved"
                          OnTaskCreated="data => HandleTaskCreated(column, data)" />
        }
    </div>
}

@code {
    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private async Task HandleTaskMoved((int TaskId, string Direction) move)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == move.TaskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Columns, task.Status);
        var newIndex = move.Direction == "left" ? currentIndex - 1 : currentIndex + 1;
        if (newIndex < 0 || newIndex >= Columns.Length) return;

        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, Columns[newIndex]);
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleTaskCreated(string column, (string Title, string Assignee, string Priority, DateTime DueDate) data)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            // If created in a column other than the default, update its status
            if (newTask.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(newTask.Id, column);
            }
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

